  "ds.own.data": "Datos procesados de esta región", "ds.own.prep": "Código de preparación de datos", "ds.own.tests": "Pruebas automáticas", "ds.own.ai": "Registro de uso de IA", "ds.own.res": "Notas de investigación", "ds.own.score": "Tabla de autoevaluación",
